 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # For each colored marker in the baseline, build a vertical stem upward.
    # Stem length is the distance to the nearest colored marker, capped by
    # available rows; markers at edges use their nearest adjacent marker.
    for r, row in enumerate(grid):
        marks = [c for c, v in enumerate(row) if v not in (0, 1)]
        for c in marks:
            left = c - max((x for x in marks if x < c), default=c)
            right = min((x for x in marks if x > c), default=c) - c
            # Use the gap from this marker to the next marker on its right;
            # at the final marker, use the previous gap.
            h = right if right else left
            for k in range(1, h + 1):
                if r-k >= 0:
                    out[r-k][c] = row[c] if k == h else 1
    return out

if __name__ == '__main__':
    demos = [
        ([[0]*10 for _ in range(9)] + [[1,1,2,1,1,1,8,1,1,1]] + [[0]*10 for _ in range(3)], [(5,2,2),(6,2,1),(7,2,1),(8,2,1),(6,6,8),(7,6,1),(8,6,1)]),
