    ]
    for g, cells in demos:
        o = transform(g)
        assert all(o[r][c] == v for r,c,v in cells)
    test = [[0]*11 for _ in range(6)] + [[1,2,1,8,1,1,1,8,1,2,1]] + [[0]*11 for _ in range(2)]
    for row in transform(test): print(*row)
    print('demo checks passed')
",
